async(page)=>{
 const results=[],base='E:/Dr.RouteFit/prototype/records/2026-10-24-incident/';
 const assert=(ok,m)=>{if(!ok)throw Error(m)};
 const role=async r=>{await page.locator(`[data-role=${r}]`).first().click();if(r==='dispatch')await page.locator('[data-dispatch-tab=map]').click()};
 const open=async a=>page.locator(`[data-action=${a}]`).first().click();
 const fill=async p=>{for(const [k,v]of Object.entries(p)){const el=page.locator(`#action-form [name=${k}]`);if(typeof v==='boolean')await el.setChecked(v);else if(await el.evaluate(x=>x.tagName)==='SELECT')await el.selectOption(String(v));else await el.fill(String(v))}};
 const submit=async()=>{await page.locator('#action-form [type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden'})};const act=async(a,p={})=>{await open(a);await fill(p);await submit()};
 const state=()=>page.evaluate(()=>JSON.parse(sessionStorage.getItem('routefit-r1-prototype-v1')));
 const parent=async()=>(await state()).orders.find(o=>o.id==='RF-1024-001');
 const select=async(id,r)=>{await role(r);if(r==='dispatch')await page.locator('#map-order-selector').selectOption(id);else if(r==='warehouse')await page.locator(`[data-order="${id}"]`).first().click();else await page.locator(`.driver-task[data-order="${id}"]`).click()};
 const start=async()=>{await role('dispatch');await open('qa');await act('reset');await role('dispatch');await open('fleet-assign');await submit();await role('driver');await act('accept');await role('warehouse');await act('prepare',{dimension:true,pattern:true,packaging:true,evidence:'DEMO-LOAD'});await role('driver');await act('pickup',{evidence:'DEMO-HANDOVER'});await act('depart');await act('report',{proof:'DEMO-ORIGINAL-CASH'});await role('dispatch');await act('incidentOpen',{reason:'演示碰撞导致车辆无法继续执行',place:'演示现场交接区',owner:'授权现场负责人 · 演示',evidence:'DEMO-INCIDENT'});};
 const assign=async(vehicle,indices)=>{await open('rescueAssign');for(const i of indices)await page.locator('[data-rescue-item]').nth(i).check();await fill({vehicle,evidence:'DEMO-ALLOCATION',safe:true,matched:true});await submit();return (await state()).orders.at(-1).id};
 const pickup=async(id,r)=>{await select(id,r);await act('rescueAccept',{available:true,cargoConfirmed:true});await open('rescuePickup');await fill({count:1,sender:'授权原保管人',receiver:'接驳司机 · 演示',evidence:'DEMO-ROADSIDE-HO',safe:true,packaging:true});await page.locator('#action-form [type=submit]').click();await page.waitForTimeout(350);assert((await page.locator('#form-error').innerText()).includes('件数'),'handover mismatch not blocked');await fill({count:(await state()).orders.find(o=>o.id===id).qty});await submit();await act('rescueDepart')};
 await page.goto('http://127.0.0.1:4173/prototype/');await page.reload();await page.setViewportSize({width:1440,height:1100});await start();assert((await state()).vehicleBlocks.V01,'accident vehicle not blocked');assert((await parent()).status==='incident_open','incident absent');
 await page.locator('[data-nav=partners]').click();await act('partnerApprove',{evidence:'DEMO-QUALIFICATION',qualified:true,matched:true});await page.locator('[data-nav=dispatch]').click();await page.locator('#map-order-selector').selectOption('RF-1024-001');
 const a=await assign('V02',[0,1]),b=await assign('PV-P01',[0,1]);assert((await parent()).incident.items.every(i=>i.custody==='事故现场原保管人'),'assignment moved custody');assert(await page.locator('[data-action=rescueAssign]').count()===0,'fully allocated still allows more');await page.locator('[data-incident-inspect]').click();await page.screenshot({path:base+'split-allocations.png',fullPage:true});
 await pickup(a,'driver');await act('rescueDeliver',{receiver:'授权收货人',evidence:'DEMO-POD-A'});assert((await parent()).status==='incident_open','first car falsely completed parent');await pickup(b,'partnerDriver');await act('rescueDeliver',{receiver:'授权收货人',evidence:'DEMO-POD-B'});assert((await parent()).status==='delivered','all items did not close');assert((await parent()).collection==='reported','rescue changed finance');assert((await state()).payables.length===1,'partner payable missing');results.push('事故冻结、两车分配、各自接单、交接差异阻断、逐车签收、原单汇总与财务独立');
 await select('RF-1024-001','dispatch');await page.locator('.incident-card details').evaluate(el=>el.open=true);await page.screenshot({path:base+'split-complete.png',fullPage:true});
 await start();const c=await assign('V02',[0,1,2,3]);await pickup(c,'driver');await act('rescueDeliver',{count:2,receiver:'授权收货人',evidence:'DEMO-PARTIAL-POD'});await select(c,'dispatch');await act('rescueReturnApprove',{reason:'其余两件拒收，授权原仓点收；已核对窗口'});await select(c,'driver');await act('rescueReturnArrived',{evidence:'DEMO-ARRIVAL'});await select(c,'warehouse');await act('rescueReturnReceive',{evidence:'DEMO-RETURN-RECEIPT'});assert((await parent()).status==='closed_exception','partial return not closed');assert((await parent()).received===2,'parent received quantity wrong');results.push('接驳部分签收、授权返仓、仓库点收后原单异常结案');
 await select('RF-1024-001','dispatch');await page.locator('.incident-card details').evaluate(el=>el.open=true);await page.screenshot({path:base+'split-returned.png',fullPage:true});await page.setViewportSize({width:390,height:844});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'mobile overflow');await page.setViewportSize({width:1440,height:1100});results.push('390px 应急调度无整页横向溢出');return {status:'PASS',checks:results};
}
